import{_ as o,c as e,o as l,a4 as t}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q17：ES6+ 重要新特性详解","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q17.md","filePath":"frontend/q17.md","lastUpdated":null}'),i={name:"frontend/q17.md"},c=t('<h1 id="q17-es6-重要新特性详解" tabindex="-1">Q17：ES6+ 重要新特性详解 <a class="header-anchor" href="#q17-es6-重要新特性详解" aria-label="Permalink to &quot;Q17：ES6+ 重要新特性详解&quot;">​</a></h1><ul><li><p><strong><code>let</code> 与 <code>const</code></strong></p><ul><li>块级作用域，无变量提升，存在暂时性死区（TDZ），不能重复声明。</li><li><code>const</code> 必须初始化，且基本类型值不可变，引用类型可修改内部属性。</li></ul></li><li><p><strong>箭头函数</strong></p><ul><li>没有自己的 <code>this</code>、<code>arguments</code>、<code>super</code>，不能用作构造函数。</li><li>语法更简洁，适合非方法函数和回调。</li></ul></li><li><p><strong>解构赋值</strong></p><ul><li>数组和对象可以模式匹配式地提取值，如 <code>const { name, age } = obj</code>。</li></ul></li><li><p><strong>模板字符串</strong></p><ul><li>反引号 `` 支持多行和变量嵌入 <code>${expression}</code>。</li></ul></li><li><p><strong>展开运算符</strong> <code>...</code></p><ul><li>可展开可迭代对象，用于数组拼接、函数参数、对象浅拷贝合并。</li></ul></li><li><p><strong>Class 语法</strong></p><ul><li>本质是原型继承的语法糖，但有了 <code>constructor</code>、<code>extends</code>、<code>super</code> 等，让继承更清晰。</li></ul></li><li><p><strong>模块化 (ESM)</strong></p><ul><li><code>import</code>/<code>export</code>，支持静态分析、tree-shaking，输出的是值的<strong>引用</strong>（CommonJS 输出值的拷贝）。ESM 是编译时加载。</li></ul></li><li><p><strong>新增数据结构</strong></p><ul><li><code>Map</code>：键值对集合，键可以是任意类型，有序。</li><li><code>Set</code>：成员唯一，可去重。</li><li><code>WeakMap</code>/<code>WeakSet</code>：键只能为对象，弱引用，不会被 GC 阻止，不可遍历。</li></ul></li><li><p><strong>Proxy 与 Reflect</strong></p><ul><li>代理对象，可拦截操作，实现响应式等元编程。</li></ul></li><li><p><strong>Promise、async/await、BigInt</strong> 等。</p></li></ul>',2),s=[c];function n(r,d,a,p,u,g){return l(),e("div",null,s)}const f=o(i,[["render",n]]);export{m as __pageData,f as default};
